export default "import { VuiSteps, Steps } from \"../../../lib\";\n\nexport const StepStatuses = () => {\n  const statusSteps: Steps = [\n    {\n      title: \"Complete Step\",\n      subTitle: \"This step has been completed\",\n      status: \"complete\"\n    },\n    {\n      title: \"Current Step\",\n      subTitle: \"This is the active step\",\n      status: \"current\"\n    },\n    {\n      title: \"Incomplete Step\",\n      subTitle: \"This step is not yet completed\",\n      status: \"incomplete\"\n    },\n    {\n      title: \"Warning Step\",\n      subTitle: \"This step has a warning\",\n      status: \"warning\"\n    },\n    {\n      title: \"Danger Step\",\n      subTitle: \"This step has an error\",\n      status: \"danger\"\n    }\n  ];\n\n  return <VuiSteps steps={statusSteps} />;\n};\n";