export default "import { BADGE_COLOR, VuiBadge, VuiFlexContainer, VuiFlexItem } from \"../../../lib\";\nimport { Subsection } from \"../../components/Subsection\";\n\nexport const BadgeColors = () => {\n  return (\n    <>\n      <Subsection title=\"Large\">\n        <VuiFlexContainer>\n          {BADGE_COLOR.map((color) => (\n            <VuiFlexItem grow={false} key={color}>\n              <VuiBadge size=\"l\" color={color}>\n                Color {color}\n              </VuiBadge>\n            </VuiFlexItem>\n          ))}\n        </VuiFlexContainer>\n      </Subsection>\n\n      <Subsection title=\"Medium\">\n        <VuiFlexContainer>\n          {BADGE_COLOR.map((color) => (\n            <VuiFlexItem grow={false} key={color}>\n              <VuiBadge size=\"m\" color={color}>\n                Color {color}\n              </VuiBadge>\n            </VuiFlexItem>\n          ))}\n        </VuiFlexContainer>\n      </Subsection>\n\n      <Subsection title=\"Small\">\n        <VuiFlexContainer>\n          {BADGE_COLOR.map((color) => (\n            <VuiFlexItem grow={false} key={color}>\n              <VuiBadge size=\"s\" color={color}>\n                Color {color}\n              </VuiBadge>\n            </VuiFlexItem>\n          ))}\n        </VuiFlexContainer>\n      </Subsection>\n    </>\n  );\n};\n";